seisSystems = Dict{String,Any}()
@time seisSystems["DSMconv"]    = shGlobalSystem(prem, gridSeis; scheme="DSMconv")
@time seisSystems["DSMconv_ref"] = shGlobalSystem(prem, gridRef; scheme="DSMconv")
@time seisSystems["OPT3"]       = shGlobalSystem(prem, gridSeis; scheme="OPT3", configs=shConfigs)
@time seisSystems["OPT5"]       = shGlobalSystem(prem, gridSeis; scheme="OPT5", configs=shConfigs)
for (k, s) in seisSystems
    @printf("%-12s n = %5d nodes, nnz(T) = %d\n", k, length(s.ξ), nnz(s.T))
end

seisSpectra = Dict{String,Any}()
for key in ("DSMconv_ref", "DSMconv", "OPT3", "OPT5")
    @time seisSpectra[key] = shSynthetics(seisSystems[key], Rprem; rs_km=rsSeis,
        force=(0.0, 0.0, 1.0), receiversθdeg=10:10:180, fmax=0.05)
end
# sanity: on φ = 0 an f_y source gives a purely transverse SH field
for (k, sp) in seisSpectra
    @printf("%-12s max|uθ|/max|uφ| = %.2e\n", k, maximum(abs.(sp.uθ)) / maximum(abs.(sp.uφ)))
end

### ⏸ Stop and review (end of Step 3b)
1. `max|uθ|/max|uφ|` ≈ round-off (pure transverse field on φ = 0);
2. record section: direct S, ScS, sS/sScS, and the (small, deep source) Love waves; all four schemes overlaid;
3. misfit to the fine DSM reference: DSM h = 10 km vs OPT3/OPT5 h = 10 km.
Caveats: the interfaces are joined by adding half-element rows (DSM-style), not yet the flexOPT overlap of Step 4; the source is a hat-function load,
not an OPT-consistent source term; no attenuation.
